mapper.select:
select count(*) from t_train_exam_paper_answer
where deleted = 0

  and train_id = #{trainId}


  and status = #{status}

select  *  from t_train_exam_paper_answer tepa
where deleted = 0 and train_id = #{trainId}

  and status = #{status}


  and user_score >= #{minScore}


  and user_score <= #{maxScore}


  and create_user = #{dataFilterUserId}


  and create_department_id in

    #{item}



  and exists (select 1 from t_user u where tepa.create_user=u.id and u.user_name like concat('%',#{userName},'%') and u.deleted= 0 )

select count(*)
from t_train_exam_paper_answer
where train_item_user_id = #{trainItemUserId}

select id from t_train_exam_paper_answer
where deleted = 0 and status = 1
and train_id = #{trainId} and id != #{id}

  and create_user = #{dataFilterUserId}


  and create_department_id in

    #{item}


limit 1
